Endurance Constants:
msg.topic = "constants";

msg.payload = {

    // ----------------------------------------
    // ENERGY
    // ----------------------------------------

    // Signal K SOC is a ratio:
    // 0.80 = 80%

    ENERGY_RESERVE_SOC: 0.50,
    ENERGY_WARNING_SOC: 0.70,

    // ----------------------------------------
    // WATER
    // ----------------------------------------

    // Fraction of total potable water remaining.

    WATER_RESERVE_RATIO: 0.20,
    WATER_WARNING_RATIO: 0.35,

    // ----------------------------------------
    // FUEL
    // ----------------------------------------

    FUEL_WARNING_RATIO: 0.30,
    FUEL_CRITICAL_RATIO: 0.20,
    FUEL_STALE_SECONDS: 1200,

    // ----------------------------------------
    // PROPANE
    // ----------------------------------------

    PROPANE_WARNING_RATIO: 0.25,
    PROPANE_CRITICAL_RATIO: 0.10,
    PROPANE_STALE_SECONDS: 86400,

    // ----------------------------------------
    // ENDURANCE WARNING WINDOWS
    // ----------------------------------------

    // Hours until intervention.

    WARNING_HOURS: 48,
    CRITICAL_HOURS: 24,

    // ----------------------------------------
    // DATA HEALTH
    // ----------------------------------------

    // Seconds before an input is considered stale.

    ENERGY_STALE_SECONDS: 300,
    WATER_STALE_SECONDS: 1200,
};

flow.set(
    "enduranceConstants",
    msg.payload
);

return msg;

Energy Endurance:
let s = msg.payload || {};

if (!s.constants) {
    return null;
}

// ----------------------------------------
// INPUTS
// ----------------------------------------

const soc =
    Number(s.batterySOC);

const prediction =
    String(
        s.energyPredictionStatus || ""
    ).toLowerCase();

const rawTimeRemainingSeconds =
    Number(s.energyTimeRemaining);

const rawTimeRemainingHours =
    rawTimeRemainingSeconds / 3600;

// ----------------------------------------
// SETTINGS
// ----------------------------------------

const ENERGY_STALE_SECONDS =
    Number(
        s.constants.ENERGY_STALE_SECONDS ?? 300
    );

const reserveSOC =
    Number(
        s.constants.ENERGY_RESERVE_SOC ?? 0.50
    );

const warningSOC =
    Number(
        s.constants.ENERGY_WARNING_SOC ?? 0.70
    );

// BMV-712 tops out at 240 hours.
// Treat 240 as effectively unlimited rather
// than a literal endurance prediction.

const BMV_MAX_HOURS = 240;

// ----------------------------------------
// DATA HEALTH
// ----------------------------------------

const socFresh =
    Number.isFinite(s.batterySOCAgeSeconds) &&
    s.batterySOCAgeSeconds <=
    ENERGY_STALE_SECONDS;

const predictionFresh =
    Number.isFinite(
        s.energyPredictionAgeSeconds
    ) &&
    s.energyPredictionAgeSeconds <=
    ENERGY_STALE_SECONDS;

const timeRemainingFresh =
    Number.isFinite(
        s.energyTimeRemainingAgeSeconds
    ) &&
    s.energyTimeRemainingAgeSeconds <=
    ENERGY_STALE_SECONDS;

const socValid =
    socFresh &&
    Number.isFinite(soc);

// Energy Predictor 0.9+ publishes:
// surplus, rising, stable, deficit, critical.
//
// Null, stale, or unknown values are deliberately
// treated as unavailable predictive context.
// They are NOT interpreted as a deficit.

const recognizedPredictionStates =
    new Set([
        "surplus",
        "rising",
        "stable",
        "deficit",
        "critical"
    ]);

const predictionValid =
    predictionFresh &&
    recognizedPredictionStates.has(
        prediction
    );

const timeRemainingValid =
    timeRemainingFresh &&
    Number.isFinite(rawTimeRemainingHours) &&
    rawTimeRemainingHours >= 0;

// ----------------------------------------
// BMV TIME REMAINING
// ----------------------------------------

const energyTimeRemainingInfinite =
    s.energyTimeRemainingInfinite === true ||
    (
        timeRemainingValid &&
        rawTimeRemainingHours >= BMV_MAX_HOURS
    );

let energyEnduranceHours = null;

if (
    timeRemainingValid &&
    !energyTimeRemainingInfinite
) {
    energyEnduranceHours =
        rawTimeRemainingHours;
}

// ----------------------------------------
// ENERGY STATUS
// ----------------------------------------
//
// Measured SOC establishes CURRENT urgency.
//
// Energy Predictor adds FUTURE context:
//
// surplus / rising / stable
//     Healthy predictive context.
//
// deficit
//     Informational WATCH when SOC is healthy.
//
// critical
//     Forecast says the bank is projected to cross
//     the chemistry critical threshold. With healthy
//     measured SOC this becomes WARNING / PLAN_CHARGE,
//     not CRITICAL: the problem is forecast, not yet
//     physically present.
//
// Missing/stale predictor data is benign. Endurance
// falls back to measured SOC and BMV time remaining.
//

let energyStatus =
    "UNKNOWN";

let energyAction =
    null;

let energyReason =
    "DATA_UNAVAILABLE";

if (!socValid) {

    energyStatus =
        "UNKNOWN";

    energyAction =
        null;

    energyReason =
        "SOC_INVALID";
}

else if (
    soc <= reserveSOC
) {

    energyStatus =
        "CRITICAL";

    energyAction =
        "CHARGE_NOW";

    energyReason =
        "SOC_RESERVE";
}

else if (
    soc <= warningSOC
) {

    energyStatus =
        "WARNING";

    energyAction =
        "PLAN_CHARGE";

    energyReason =
        "SOC_LOW";
}

else if (
    predictionValid &&
    prediction === "critical"
) {

    energyStatus =
        "WARNING";

    energyAction =
        "PLAN_CHARGE";

    energyReason =
        "PREDICTED_CRITICAL";
}

else if (
    predictionValid &&
    prediction === "deficit"
) {

    energyStatus =
        "WATCH";

    energyAction =
        "NONE";

    energyReason =
        "PREDICTED_DEFICIT";
}

else if (
    predictionValid &&
    prediction === "surplus"
) {

    energyStatus =
        "OK";

    energyAction =
        "NONE";

    energyReason =
        "PREDICTED_SURPLUS";
}

else if (
    predictionValid &&
    prediction === "rising"
) {

    energyStatus =
        "OK";

    energyAction =
        "NONE";

    energyReason =
        "PREDICTED_RISING";
}

else if (
    predictionValid &&
    prediction === "stable"
) {

    energyStatus =
        "OK";

    energyAction =
        "NONE";

    energyReason =
        "PREDICTED_STABLE";
}

else {

    energyStatus =
        "OK";

    energyAction =
        "NONE";

    energyReason =
        "SOC_HEALTHY_PREDICTION_UNAVAILABLE";
}

// ----------------------------------------
// UPDATE STATE
// ----------------------------------------

s.energyTimeRemainingRawHours =
    timeRemainingValid
        ? rawTimeRemainingHours
        : null;

s.energyTimeRemainingInfinite =
    energyTimeRemainingInfinite;

s.energyEnduranceHours =
    energyEnduranceHours;

s.energyStatus =
    energyStatus;

s.energyAction =
    energyAction;

s.energyReason =
    energyReason;

s.energyDataValid =
    socValid;

s.energyPredictionValid =
    predictionValid;

s.energyPredictionStatusNormalized =
    predictionValid
        ? prediction
        : null;

s.energyTimeRemainingValid =
    timeRemainingValid;

// ----------------------------------------
// OUTPUT
// ----------------------------------------

msg.payload = s;

return msg;

Fuel Endurance:
let s = msg.payload || {};

if (!s.constants) {
    return null;
}

// ----------------------------------------
// INPUTS
// ----------------------------------------

const fuelLevel =
    Number(s.fuelLevel);

const fuelVolume =
    Number(s.fuelVolume);

const fuelTimeRemaining =
    Number(s.fuelTimeRemaining);

// ----------------------------------------
// SETTINGS
// ----------------------------------------

const FUEL_STALE_SECONDS =
    Number(
        s.constants.FUEL_STALE_SECONDS ?? 1200
    );

const FUEL_WARNING_RATIO =
    Number(
        s.constants.FUEL_WARNING_RATIO ?? 0.30
    );

const FUEL_CRITICAL_RATIO =
    Number(
        s.constants.FUEL_CRITICAL_RATIO ?? 0.20
    );

// ----------------------------------------
// DATA HEALTH
// ----------------------------------------

const levelFresh =
    Number.isFinite(
        s.fuelLevelAgeSeconds
    ) &&
    s.fuelLevelAgeSeconds <=
    FUEL_STALE_SECONDS;

const volumeFresh =
    Number.isFinite(
        s.fuelVolumeAgeSeconds
    ) &&
    s.fuelVolumeAgeSeconds <=
    FUEL_STALE_SECONDS;

const levelValid =
    levelFresh &&
    Number.isFinite(fuelLevel) &&
    fuelLevel >= 0 &&
    fuelLevel <= 1;

const volumeValid =
    volumeFresh &&
    Number.isFinite(fuelVolume) &&
    fuelVolume >= 0;

// Retained running-engine capability.
// Useful information, but not the basis
// for present fuel intervention status.

const timeValid =
    Number.isFinite(fuelTimeRemaining) &&
    fuelTimeRemaining > 0;

// ----------------------------------------
// FUEL STATUS
// ----------------------------------------

let fuelStatus =
    "UNKNOWN";

let fuelAction =
    "NONE";

let fuelReason =
    "DATA_UNAVAILABLE";

if (levelValid) {

    if (
        fuelLevel <=
        FUEL_CRITICAL_RATIO
    ) {

        fuelStatus =
            "CRITICAL";

        fuelAction =
            "REFUEL_NOW";

        fuelReason =
            "FUEL_RESERVE_CRITICAL";
    }

    else if (
        fuelLevel <=
        FUEL_WARNING_RATIO
    ) {

        fuelStatus =
            "WARNING";

        fuelAction =
            "PLAN_REFUEL";

        fuelReason =
            "FUEL_RESERVE_LOW";
    }

    else {

        fuelStatus =
            "OK";

        fuelAction =
            "NONE";

        fuelReason =
            "FUEL_HEALTHY";
    }
}

// ----------------------------------------
// SUPPORTING CAPABILITY
// ----------------------------------------

let fuelEnduranceHours =
    null;

if (timeValid) {

    fuelEnduranceHours =
        fuelTimeRemaining / 3600;
}

// ----------------------------------------
// UPDATE STATE
// ----------------------------------------

s.fuelLevelRatio =
    levelValid
        ? fuelLevel
        : null;

s.fuelVolumeM3 =
    volumeValid
        ? fuelVolume
        : null;

s.fuelEnduranceHours =
    fuelEnduranceHours;

s.fuelStatus =
    fuelStatus;

s.fuelAction =
    fuelAction;

s.fuelReason =
    fuelReason;

// Fuel status fundamentally depends on
// current tank level.
//
// Volume and retained range-time are
// supporting information.

s.fuelDataValid =
    levelValid;

s.fuelVolumeValid =
    volumeValid;

s.fuelTimeRemainingValid =
    timeValid;

// ----------------------------------------
// OUTPUT
// ----------------------------------------

msg.payload = s;

return msg;

Propane Endurance:
let s = msg.payload || {};

if (!s.constants) {
    return null;
}

// ----------------------------------------
// INPUT
// ----------------------------------------

const propaneLevel =
    Number(s.propaneLevel);

// ----------------------------------------
// SETTINGS
// ----------------------------------------

const PROPANE_STALE_SECONDS =
    Number(
        s.constants.PROPANE_STALE_SECONDS ?? 86400
    );

const PROPANE_WARNING_RATIO =
    Number(
        s.constants.PROPANE_WARNING_RATIO ?? 0.25
    );

const PROPANE_CRITICAL_RATIO =
    Number(
        s.constants.PROPANE_CRITICAL_RATIO ?? 0.10
    );

// ----------------------------------------
// DATA HEALTH
// ----------------------------------------

const levelFresh =
    Number.isFinite(
        s.propaneLevelAgeSeconds
    ) &&
    s.propaneLevelAgeSeconds <=
    PROPANE_STALE_SECONDS;

const levelValid =
    levelFresh &&
    Number.isFinite(propaneLevel) &&
    propaneLevel >= 0 &&
    propaneLevel <= 1;

// ----------------------------------------
// PROPANE STATUS
// ----------------------------------------

let propaneStatus =
    "UNKNOWN";

let propaneAction =
    "NONE";

let propaneReason =
    "DATA_UNAVAILABLE";

if (levelValid) {

    if (
        propaneLevel <=
        PROPANE_CRITICAL_RATIO
    ) {

        propaneStatus =
            "CRITICAL";

        propaneAction =
            "CONSERVE_PROPANE";

        propaneReason =
            "PROPANE_RESERVE_CRITICAL";
    }

    else if (
        propaneLevel <=
        PROPANE_WARNING_RATIO
    ) {

        propaneStatus =
            "WARNING";

        propaneAction =
            "PLAN_PROPANE_REFILL";

        propaneReason =
            "PROPANE_RESERVE_LOW";
    }

    else {

        propaneStatus =
            "OK";

        propaneAction =
            "NONE";

        propaneReason =
            "PROPANE_HEALTHY";
    }
}

// ----------------------------------------
// UPDATE STATE
// ----------------------------------------

s.propaneLevelRatio =
    levelValid
        ? propaneLevel
        : null;

s.propaneStatus =
    propaneStatus;

s.propaneAction =
    propaneAction;

s.propaneReason =
    propaneReason;

s.propaneDataValid =
    levelValid;

// ----------------------------------------
// OUTPUT
// ----------------------------------------

msg.payload = s;

return msg;
